// Generates docs/reference/cli.md from the management command table (P2-10, L-134). Run: pnpm docs:cli
// Check (tests): scripts/test/cli-reference.test.ts compares the committed file with render().
import { writeFileSync } from 'node:fs';
import { COMMANDS, usage } from '../apps/cli/src/manage/commands.ts';

const OUT = new URL('../docs/reference/cli.md', import.meta.url);

export function render(): string {
  const lines = [
    '<!-- Generated by scripts/cli-reference.ts (pnpm docs:cli); do not edit. -->',
    '# CLI reference',
    '',
    '`agility-bridge` with no command (or `stdio`) serves MCP on stdin/stdout; `agility-bridge serve` runs the HTTP',
    'server. The commands below manage a server: locally over its database (default) or remotely through the admin API',
    'when `AB_ADMIN_URL` is set ([guide](../guide/cli.md)). Output is JSON on stdout. Secrets are never arguments.',
    '',
  ];
  let group = '';
  for (const spec of COMMANDS) {
    const head = spec.words[0] as string;
    if (head !== group) {
      group = head;
      lines.push(`## ${head}`, '');
    }
    lines.push(
      `### \`${spec.words.join(' ')}\``,
      '',
      `${spec.summary}.`,
      '',
      '```text',
      usage(spec),
      '```',
      '',
    );
    const rows = [
      ...(spec.args ?? []).map((a) => `| \`<${a.name}>\` | argument | ${a.help} |`),
      ...(spec.options ?? []).map(
        (o) =>
          `| \`--${o.name}\` | ${o.kind}${o.repeat ? ', repeatable' : ''}${o.required ? ', required' : ''} | ${o.help} |`,
      ),
    ];
    if (rows.length > 0) lines.push('| Name | Kind | Meaning |', '|---|---|---|', ...rows, '');
    lines.push(
      spec.local !== undefined
        ? 'Local database only.'
        : spec.run !== undefined
          ? 'Runs without a server.'
          : 'Local or remote.',
      '',
    );
  }
  return lines.join('\n');
}

if (import.meta.main) {
  writeFileSync(OUT, render());
  console.error('wrote docs/reference/cli.md');
}
